const V={screen:'dashboard',sector:'emlak',navHistory:[],data:{clients:[],properties:[],quotes:[],jobs:[],tasks:[],payments:[],costEntries:[],subscriptions:[],creditLedger:[],audit:[],pricing:[],qrLinks:[],marketSources:[]},cloudHealthy:false,googleAds:{loading:false,ok:false,customers:[],managerCustomerId:'1383282213',error:null}};
const CLOUD=window.VertexCloud;

const TR={aktif:'Aktif',pasif:'Pasif',arsiv:'Arşiv',bekliyor:'Bekliyor',kabul_edildi:'Kabul edildi',planlandi:'Planlandı',cekildi:'Çekildi',duzenleniyor:'Düzenleniyor',musteri_onayi:'Müşteri onayı',teslim_edildi:'Teslim edildi',odeme_bekliyor:'Ödeme bekliyor',odendi:'Ödendi',tamamlandi:'Tamamlandı'};
const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const val=id=>document.getElementById(id)?.value?.trim()||'';
function cloudErr(e){console.error(e);alert('İşlem tamamlanamadı: '+(e?.message||e))}
async function audit(action,entity='',entityId=null){try{const {data:{user}}=await CLOUD.auth.getUser();if(user)await CLOUD.from('audit_logs').insert({user_id:user.id,action,entity_type:entity,entity_id:entityId})}catch(e){console.warn(e)}}
async function loadCloud(){
 const names=['clients','properties','quotes','jobs','tasks','payments','audit_logs','quote_items','qr_links','market_sources','cost_entries','subscriptions','credit_ledger'];
 const r=await Promise.all(names.map(async n=>{const rows=[],pageSize=500,max=n==='audit_logs'?50:Infinity;for(let from=0;from<max;from+=pageSize){const size=Math.min(pageSize,max-from);const {data,error}=await CLOUD.from(n).select('*').order('created_at',{ascending:false}).range(from,from+size-1);if(error)throw error;rows.push(...data);if(data.length<size)break}return rows}));
 const [cl,pr,qu,jo,ta,pa,au,qi,qr,market,costs,subs,credits]=r, cm=Object.fromEntries(cl.map(x=>[x.id,x.name]));
 V.data.clients=cl.map(x=>({...x,contact:x.contact_person}));
 V.data.properties=pr.map(x=>({...x,name:x.title,client:cm[x.client_id]||'—',type:x.property_type,tour:TR[x.tour_status]||x.tour_status,qr:TR[x.qr_status]||x.qr_status,status:TR[x.listing_status]||x.listing_status}));
 V.data.quotes=qu.map(x=>({...x,client:cm[x.client_id]||'—',amount:x.total,property:x.notes||x.quote_no||'Teklif',items:qi.filter(i=>i.quote_id===x.id)}));
 V.data.jobs=jo.map(x=>({...x,client:cm[x.client_id]||'—',date:x.scheduled_at?new Date(x.scheduled_at).toLocaleString('tr-TR'):'Planlanmadı'}));
 V.data.tasks=ta.map(x=>({...x,date:x.due_at?new Date(x.due_at).toLocaleString('tr-TR'):'Tarih yok'}));
 V.data.payments=pa;V.data.qrLinks=qr;V.data.marketSources=market;V.data.costEntries=costs;V.data.subscriptions=subs;V.data.creditLedger=credits;V.data.audit=au.map(x=>({at:new Date(x.created_at).toLocaleString('tr-TR'),action:x.action}));
 try{const {data:ps,error:pe}=await CLOUD.from('pricing_settings').select('*');if(!pe)V.data.pricing=ps||[];else console.warn('Pricing settings unavailable',pe)}catch(e){console.warn('Pricing settings load failed',e)}
 V.cloudHealthy=true;
}
const icons={dashboard:'⌂',quotes:'▤',jobs:'✓',calendar:'▦',clients:'●',properties:'⌂',qr:'▦',subscriptions:'◈',market:'▥',gallery:'▣',costs:'₺',pricing:'$',health:'◆',admin:'⚙'};
function nav(){return [['dashboard','Panel'],['quotes','Teklifler'],['jobs','İşler'],['calendar','Takvim / Görevler'],['clients','Müşteriler'],['properties','Mülkler'],['qr','Dinamik QR'],['subscriptions','Abonelik / Kredi'],['market','Piyasa'],['gallery','Örnek Galeri'],['costs','Finans Merkezi'],['pricing','Fiyat Merkezi'],['health','Sistem Sağlığı'],['admin','Uzaktan Yönetim']].filter(([k])=>k!=='properties'||V.sector==='emlak').map(([k,t])=>'<button class="'+(V.screen===k?'active':'')+'" onclick="go(\''+k+'\')"><span class="ni">'+icons[k]+'</span><span>'+t+'</span></button>').join('')}
function layout(body,title,sub='VERTEX SUPER ADMIN'){const back=V.screen!=='dashboard'?'<button class="back-btn" onclick="goBack()" aria-label="Geri dön"><span>←</span> Geri</button>':'';return '<div class="shell"><aside class="side"><div class="brand"><div class="brand-mark"><img src="'+VERTEX_LOGO+'"></div><div><b>VERTEX</b><small>FLUX 2.0</small></div></div><div class="nav">'+nav()+'<div class="sep"></div><button onclick="presentation()">▣ <span>Müşteri Sunumu</span></button><button onclick="logout()">⇥ <span>Kilitle</span></button></div></aside><main class="main">'+back+'<div class="top"><div><div class="eyebrow">'+sub+'</div><h1>'+title+'</h1></div><div class="actions"><button class="btn" onclick="backup()">Yedek Al</button><button class="btn primary" onclick="newQuote()">+ Yeni Teklif</button></div></div>'+body+'</main></div>'}
function sectorCards(){const a=[['emlak','EMLAK','360° Portföy Yönetimi','Mülk · 360° Tur · QR · Portföy'],['kuyum','KUYUM','Premium Ürün Deneyimi','Mücevher · Görsel · Video · Dijital Mağaza'],['otel','OTEL & TURİZM','Mekân Deneyimi','Tesis · Oda · 360° · Drone · QR']];return '<div class="sector-grid">'+a.map((c,i)=>'<button class="sector-card sector-'+c[0]+'" onclick="openSectorWorkspace(\''+c[0]+'\')"><div class="sector-visual"><div class="sector-art">'+VERTEX_SECTOR_ART[c[0]]+'</div><span class="sector-number">0'+(i+1)+'</span></div><div class="sector-copy"><span class="sector-kicker">'+c[2]+'</span><h3>'+c[1]+'</h3><p>'+c[3]+'</p><span class="sector-enter">ÇALIŞMA ALANINA GİR →</span></div></button>').join('')+'</div>'}
function dashboard(){const d=V.data;return layout('<div class="dashboard-hero"><h2>VERTEX <span>Kontrol Merkezi</span></h2><p>Üç sektörün operasyonunu tek merkezden yönetin.</p></div><div class="grid stats"><div class="card stat"><span>Müşteri</span><strong>'+d.clients.length+'</strong></div><div class="card stat"><span>İş</span><strong>'+d.jobs.length+'</strong></div><div class="card stat"><span>Mülk</span><strong>'+d.properties.length+'</strong></div><div class="card stat"><span>Bulut</span><strong class="'+(V.cloudHealthy?'ok':'warn')+'">'+(V.cloudHealthy?'Bağlı':'Kontrol')+'</strong></div></div>'+sectorCards(),'Kontrol Merkezi')}
function goBack(){if(document.getElementById('vfModal'))return closeModal();const previous=V.navHistory.pop();V.screen=previous?.screen||'dashboard';if(previous?.sector)V.sector=previous.sector;render()}
function openSectorWorkspace(s){V.navHistory.push({screen:V.screen,sector:V.sector});V.sector=s;V.screen='sectorWorkspace';render()}
function sectorWorkspace(){const cfg={emlak:['EMLAK ÇALIŞMA ALANI','360° PORTFÖY YÖNETİMİ',[['Müşteriler','clients'],['Mülkler','properties'],['Teklifler','quotes'],['İşler','jobs'],['Takvim','calendar'],['Finans','costs'],['Fiyat Listesi','pricing']]],kuyum:['KUYUM ÇALIŞMA ALANI','PREMİUM ÜRÜN DENEYİMİ',[['Müşteriler','clients'],['Ürün Görselleri','gallery'],['Reklam Filmleri','gallery'],['Teklifler','quotes'],['Takvim','calendar'],['Fiyat Listesi','pricing'],['Müşteri Sunumu','presentation']]],otel:['OTEL & TURİZM ÇALIŞMA ALANI','MEKÂN DENEYİMİ',[['Müşteriler','clients'],['360° Tesis Turu','presentation'],['Drone','presentation'],['Teklifler','quotes'],['Takvim','calendar'],['Fiyat Listesi','pricing'],['Müşteri Sunumu','presentation']]]};const d=cfg[V.sector];return layout('<div class="workspace-hero workspace-'+V.sector+'"><div class="eyebrow">'+d[1]+'</div><h2>'+d[0]+'</h2><p>Bu sektöre ait müşteri, içerik, teklif ve operasyon araçları.</p></div><div class="workspace-grid">'+d[2].map((a,i)=>'<button class="workspace-action" onclick="'+(a[1]==='presentation'?'presentation(\''+V.sector+'\')':'go(\''+a[1]+'\')')+'"><span>0'+(i+1)+'</span><div><b>'+a[0]+'</b><small>Aç ve yönet</small></div><i>→</i></button>').join('')+'</div>',d[0],d[1])}
function clients(){const rows=V.data.clients.filter(x=>x.sector===V.sector).map(c=>'<div class="row"><b>'+esc(c.name)+'</b><span>'+esc((c.sector||'').toUpperCase())+'</span><span class="ok">● '+esc(TR[c.status]||c.status)+'</span><button class="btn" onclick="clientDetail(\''+c.id+'\')">Aç</button></div>').join('');return layout('<div class="card"><div class="section-title"><h2>Müşteriler</h2><button class="btn primary" onclick="addClient()">+ Müşteri Ekle</button></div><div class="list">'+(rows||'<div class="empty-state">Henüz müşteri yok.</div>')+'</div></div>','Müşteriler')}
function properties(){const rows=V.data.properties.map(p=>'<div class="row"><b>'+esc(p.name)+'<br><small class="muted">'+esc(p.client)+'</small></b><span>'+esc(p.sqm||0)+' m²</span><span>360: '+esc(p.tour)+' · QR: '+V.data.qrLinks.filter(q=>q.property_id===p.id).length+'</span><button class="btn" onclick="propertyDetail(\''+p.id+'\')">Yönet</button></div>').join('');return layout('<div class="card"><div class="section-title"><h2>Emlak Mülkleri</h2><button class="btn primary" onclick="addProperty()">+ Mülk Ekle</button></div><div class="list">'+(rows||'<div class="empty-state">Henüz mülk yok.</div>')+'</div></div>','Mülkler','EMLAK · PORTFÖY')}
function qr(){const rows=V.data.qrLinks.map(x=>{const url=location.origin+'/q/'+x.slug;return '<div class="row"><b>'+esc(x.title)+'<br><small class="muted">'+esc(url)+'</small></b><span>'+Number(x.scans||0)+' tarama</span><span>'+esc(x.active?'Aktif':'Pasif')+'</span><button class="btn" onclick="editQR(\''+x.id+'\')">Yönet</button></div>'}).join('');const report=(V.qrReport||[]).map(r=>'<div class="row"><b>'+esc(r.month)+'</b><span>'+esc(V.data.qrLinks.find(x=>x.slug===r.slug)?.title||r.slug)+'</span><strong>'+Number(r.scans)+' tarama</strong></div>').join('');return layout('<div class="card"><div class="section-title"><h2>Dinamik QR Bağlantıları</h2><button class="btn primary" onclick="newQR()">+ QR Oluştur</button></div><p class="muted">Basılı kodun adresi sabit kalır. Hedef bağlantıyı dilediğiniz zaman değiştirebilirsiniz.</p><div class="list">'+(rows||'<div class="empty-state">Henüz QR bağlantısı yok.</div>')+'</div></div><div class="card"><div class="section-title"><h2>Aylık Tarama Raporu</h2><button class="btn" onclick="loadQRReport()">Raporu Güncelle</button></div>'+(report||'<p class="muted">Aylık verileri görmek için raporu güncelleyin.</p>')+'</div>','Dinamik QR')}
function subscriptions(){const cm=Object.fromEntries(V.data.clients.map(c=>[c.id,c.name])),rows=V.data.subscriptions.map(s=>'<div class="row"><b>'+esc(cm[s.client_id]||'Müşteri')+'<br><small class="muted">'+esc(s.plan_name)+'</small></b><span>'+money(s.monthly_price)+' / ay</span><span>Sonraki: '+esc(s.next_renewal)+'</span><button class="btn" onclick="renewSubscription(\''+s.id+'\')" '+(s.status!=='active'?'disabled':'')+'>Dönemi Yenile</button></div>').join('');const balances=V.data.clients.map(c=>({name:c.name,balance:V.data.creditLedger.filter(x=>x.client_id===c.id).reduce((n,x)=>n+Number(x.amount),0)})).filter(x=>x.balance!==0).map(x=>'<div class="row"><b>'+esc(x.name)+'</b><strong>'+Number(x.balance).toLocaleString('tr-TR')+' kredi</strong></div>').join('');return layout('<div class="card"><div class="section-title"><h2>Abonelikler</h2><button class="btn primary" onclick="newSubscription()">+ Abonelik Ekle</button></div><p class="muted">Yenileme, vade tarihinde elle yapılır. Bu ekran otomatik ödeme almaz.</p>'+(rows||'<div class="empty-state">Abonelik yok.</div>')+'</div><div class="card"><div class="section-title"><h2>Kredi Bakiyeleri</h2><button class="btn" onclick="adjustCredit()">+ Kredi İşlemi</button></div>'+(balances||'<p class="muted">Henüz kredi işlemi yok.</p>')+'</div>','Abonelik / Kredi','GİZLİ · SUPER ADMIN')}
function newSubscription(){modal('Abonelik Ekle','<div class="form"><label>Müşteri<select id="subClient">'+V.data.clients.filter(c=>c.status==='aktif').map(c=>'<option value="'+c.id+'">'+esc(c.name)+'</option>').join('')+'</select></label><label>Plan adı<input id="subPlan"></label><label>Aylık fiyat (TL)<input id="subPrice" type="number" min="0"></label><label>Aylık kredi<input id="subCredits" type="number" min="0"></label><label>Sonraki yenileme<input id="subRenewal" type="date"></label></div>','<button class="btn" onclick="closeModal()">Vazgeç</button><button class="btn primary" onclick="saveSubscription()">Kaydet</button>')}
async function saveSubscription(){const client=val('subClient'),plan=val('subPlan'),price=Number(val('subPrice')),credits=Number(val('subCredits'));if(!client||!plan||!Number.isFinite(price)||price<0||!Number.isFinite(credits)||credits<0||!val('subRenewal'))return alert('Müşteri, plan, fiyat, kredi ve yenileme tarihi gerekli.');const {data:{user}}=await CLOUD.auth.getUser();const {error}=await CLOUD.from('subscriptions').insert({client_id:client,plan_name:plan,monthly_price:price,monthly_credits:credits,next_renewal:val('subRenewal'),created_by:user.id});if(error)return cloudErr(error);closeModal();await refresh()}
async function renewSubscription(id){const s=V.data.subscriptions.find(x=>x.id===id);if(!s)return;if(new Date(s.next_renewal+'T00:00:00')>new Date())return alert('Yenileme tarihi henüz gelmedi.');if(!confirm('Abonelik dönemini yenileyip '+s.monthly_credits+' kredi ekleyelim mi?'))return;const {error}=await CLOUD.rpc('vertex_renew_subscription',{p_id:id});if(error)return cloudErr(error);await refresh()}
function adjustCredit(){modal('Kredi İşlemi','<div class="form"><label>Müşteri<select id="creditClient">'+V.data.clients.map(c=>'<option value="'+c.id+'">'+esc(c.name)+'</option>').join('')+'</select></label><label>Değişim (+ ekle / − kullan)<input id="creditAmount" type="number" step="1"></label><label>Açıklama<input id="creditNote"></label></div>','<button class="btn" onclick="closeModal()">Vazgeç</button><button class="btn primary" onclick="saveCredit()">Kaydet</button>')}
async function saveCredit(){const client=val('creditClient'),amount=Number(val('creditAmount')),note=val('creditNote');if(!client||!Number.isFinite(amount)||amount===0||!note)return alert('Müşteri, sıfırdan farklı tutar ve açıklama gerekli.');const balance=V.data.creditLedger.filter(x=>x.client_id===client).reduce((n,x)=>n+Number(x.amount),0);if(balance+amount<0)return alert('Kredi bakiyesi eksiye düşemez.');const {data:{user}}=await CLOUD.auth.getUser();const {error}=await CLOUD.from('credit_ledger').insert({client_id:client,amount,note,created_by:user.id});if(error)return cloudErr(error);closeModal();await refresh()}
async function loadQRReport(){const {data,error}=await CLOUD.rpc('vertex_qr_monthly_report');if(error)return cloudErr(error);V.qrReport=data||[];render()}
function newQR(propertyId){const p=V.data.properties.find(x=>x.id===propertyId);modal('Dinamik QR Oluştur','<div class="form"><label>Başlık<input id="qrTitle" placeholder="Örn. Lara 3+1" value="'+esc(p?.title||'')+'"></label><label>Hedef bağlantı (https://)<input id="qrTarget" type="url" placeholder="https://..." value="'+esc(p?.tour_url||'')+'"></label><label>Müşteri<select id="qrClient"><option value="">Bağımsız</option>'+V.data.clients.map(c=>'<option value="'+c.id+'">'+esc(c.name)+'</option>').join('')+'</select></label><label>Mülk<select id="qrProperty"><option value="">Mülke bağlı değil</option>'+V.data.properties.map(x=>'<option value="'+x.id+'">'+esc(x.title)+'</option>').join('')+'</select></label></div>','<button class="btn" onclick="closeModal()">Vazgeç</button><button class="btn primary" onclick="saveQR()">Oluştur</button>');if(p){document.getElementById('qrClient').value=p.client_id;document.getElementById('qrProperty').value=p.id}}
async function saveQR(){const title=val('qrTitle'),target=val('qrTarget'),propertyId=val('qrProperty');if(!title||!/^https:\/\/[^\s]+$/i.test(target))return alert('Başlık ve geçerli HTTPS bağlantısı gerekli.');const property=V.data.properties.find(x=>x.id===propertyId);const slug='vf-'+crypto.randomUUID().slice(0,12);const {data:{user}}=await CLOUD.auth.getUser();const {error}=await CLOUD.from('qr_links').insert({slug,title,target_url:target,client_id:property?.client_id||val('qrClient')||null,property_id:propertyId||null,created_by:user.id});if(error)return cloudErr(error);closeModal();await audit('Dinamik QR oluşturuldu','qr_links');await refresh()}
function editQR(id){const x=V.data.qrLinks.find(a=>a.id===id);if(!x)return;const url=location.origin+'/q/'+x.slug,qrImage='https://api.qrserver.com/v1/create-qr-code/?size=600x600&ecc=H&data='+encodeURIComponent(url);modal('Dinamik QR Yönet','<p>Sabit bağlantı: <a href="'+esc(url)+'" target="_blank" rel="noopener">'+esc(url)+'</a></p><p>'+Number(x.scans||0)+' tarama</p><div class="qr-preview"><img src="'+esc(qrImage)+'" alt="Bu bağlantıyı açan QR kod" width="220" height="220"><a class="btn" href="'+esc(qrImage)+'" target="_blank" rel="noopener">Baskı için QR görselini aç</a></div><div class="form"><label>Başlık<input id="qrEditTitle" value="'+esc(x.title)+'"></label><label>Hedef bağlantı<input id="qrEditTarget" type="url" value="'+esc(x.target_url)+'"></label><label>Durum<select id="qrEditActive"><option value="true">Aktif</option><option value="false">Pasif</option></select></label></div>','<button class="btn" onclick="copyQR(\''+x.slug+'\')">Sabit bağlantıyı kopyala</button><button class="btn primary" onclick="updateQR(\''+id+'\')">Kaydet</button>');document.getElementById('qrEditActive').value=String(x.active)}
async function copyQR(slug){await navigator.clipboard.writeText(location.origin+'/q/'+slug);alert('Sabit bağlantı kopyalandı.')}
async function updateQR(id){const title=val('qrEditTitle'),target=val('qrEditTarget');if(!title||!/^https:\/\/[^\s]+$/i.test(target))return alert('Başlık ve geçerli HTTPS bağlantısı gerekli.');const {error}=await CLOUD.from('qr_links').update({title,target_url:target,active:val('qrEditActive')==='true',updated_at:new Date().toISOString()}).eq('id',id);if(error)return cloudErr(error);closeModal();await audit('QR hedefi güncellendi','qr_links',id);await refresh()}
function quotes(){
 const clients=V.data.clients.filter(x=>x.sector===V.sector&&x.status==='aktif');
 const rows=V.data.quotes.filter(q=>q.sector===V.sector).map(q=>'<div class="row"><b>'+esc(q.quote_no||q.property)+'</b><span>'+esc(q.client)+'</span><span>'+money(q.total)+'</span><button class="btn" onclick="quoteDetail(\''+q.id+'\')">İncele</button></div>').join('');
 return layout('<div class="grid cols"><div class="card"><h2>Yeni Teklif</h2><div class="form"><label>Müşteri<select id="qClient">'+clients.map(x=>'<option value="'+x.id+'">'+esc(x.name)+'</option>').join('')+'</select></label><label>Mülk / Proje<input id="qProperty"></label><label>Hizmet<input id="qService" placeholder="Örn. 360° Sanal Tur"></label><label>Tutar (TL)<input id="qAmount" type="number" min="1"></label></div><button class="btn primary" onclick="createQuote()" '+(!clients.length?'disabled':'')+'>Teklifi Kaydet</button>'+(!clients.length?'<p class="muted">Önce bu sektöre müşteri ekleyin.</p>':'')+'</div><div class="card"><h2>Kayıtlı Teklifler</h2>'+(rows||'<div class="empty-state">Henüz teklif yok.</div>')+'</div></div>','Teklifler')
}
function quoteDetail(id){const q=V.data.quotes.find(x=>x.id===id);if(!q)return;const items=q.items||[];const lines=items.map(i=>'<div class="row"><span>'+esc(i.description)+'</span><b>'+money(i.total)+'</b></div>').join('');const accepted=q.status==='kabul_edildi';modal('Teklif '+esc(q.quote_no||''),'<p>'+esc(q.client)+' · '+esc(TR[q.status]||q.status)+'</p><div class="list">'+(lines||'<p class="muted">Kalem bulunamadı.</p>')+'</div><h2>Toplam: '+money(q.total)+'</h2><p class="muted">'+esc(q.notes||'')+'</p>','<button class="btn" onclick="closeModal()">Kapat</button><button class="btn" onclick="window.print()">Yazdır / PDF</button>'+(accepted?'':'<button class="btn primary" onclick="acceptQuote(\''+q.id+'\')">Teklifi Kabul Et ve İş Aç</button>'))}
function jobs(){const steps=['kabul_edildi','planlandi','cekildi','duzenleniyor','musteri_onayi','teslim_edildi','odeme_bekliyor','odendi'];const sectorClientIds=new Set(V.data.clients.filter(c=>c.sector===V.sector).map(c=>c.id));const rows=V.data.jobs.filter(j=>sectorClientIds.has(j.client_id)).map(j=>'<div class="card"><div class="section-title"><h2>'+esc(j.title)+'</h2><span class="pill">'+esc(j.client)+'</span></div><p class="muted">'+esc(j.date)+'</p><div class="job-controls"><button class="btn" onclick="scheduleJob(\''+j.id+'\')">Çekim / iş tarihi belirle</button><button class="btn" onclick="paymentForJob(\''+j.id+'\')">Ödeme kaydı aç</button></div><div class="timeline">'+steps.map(s=>'<button class="step '+(j.status===s?'done':'')+'" onclick="setJobStatus(\''+j.id+'\',\''+s+'\')">'+TR[s]+'</button>').join('')+'</div></div>').join('');return layout('<div class="list">'+(rows||'<div class="empty-state">Henüz iş yok.</div>')+'</div>','İşler','TEKLİFTEN TESLİMATA')}
function localDateTimeValue(value){const d=new Date(value);if(!Number.isFinite(d.getTime()))return '';const local=new Date(d.getTime()-d.getTimezoneOffset()*60000);return local.toISOString().slice(0,16)}
function scheduleJob(id){const j=V.data.jobs.find(x=>x.id===id);if(!j)return;modal('İşi Planla','<div class="form"><label>Tarih ve saat<input id="jobDate" type="datetime-local"></label><label>Not<input id="jobNote" value="'+esc(j.notes||'')+'"></label></div>','<button class="btn" onclick="closeModal()">Vazgeç</button><button class="btn primary" onclick="saveJobSchedule(\''+id+'\')">Planı Kaydet</button>');if(j.scheduled_at)document.getElementById('jobDate').value=localDateTimeValue(j.scheduled_at)}
async function saveJobSchedule(id){const date=val('jobDate');if(!date)return alert('Tarih ve saat seçin.');const iso=new Date(date).toISOString();const {error}=await CLOUD.from('jobs').update({scheduled_at:iso,notes:val('jobNote'),status:'planlandi'}).eq('id',id);if(error)return cloudErr(error);await audit('İş planlandı','jobs',id);closeModal();await refresh()}
function calendar(){const rows=V.data.tasks.map(t=>'<div class="row"><b>'+esc(t.date)+'</b><span>'+esc(t.title)+'</span><span class="pill">'+esc(TR[t.status]||t.status)+'</span><button class="btn" onclick="completeTask(\''+t.id+'\')">Tamamla</button></div>').join('');return layout('<div class="grid cols"><div class="card"><h2>Takvim</h2>'+(rows||'<div class="empty-state">Görev yok.</div>')+'</div><div class="card"><h2>Yeni Görev</h2><div class="form"><label>Görev<input id="taskTitle"></label><label>Tarih<input id="taskDate" type="datetime-local"></label></div><button class="btn primary" onclick="addTask()">Görev Ekle</button></div></div>','Takvim / Görevler')}
function costs(){const p=V.data.payments,paid=p.filter(x=>x.status==='odendi').reduce((a,x)=>a+Number(x.amount||0),0),pending=p.filter(x=>x.status==='bekliyor').reduce((a,x)=>a+Number(x.amount||0),0),expense=V.data.costEntries.reduce((a,x)=>a+Number(x.amount||0),0);return layout('<div class="grid stats"><div class="card stat"><span>Tahsil</span><strong>'+money(paid)+'</strong></div><div class="card stat"><span>Bekleyen</span><strong>'+money(pending)+'</strong></div><div class="card stat"><span>Gider</span><strong>'+money(expense)+'</strong></div><div class="card stat"><span>Tahsilat − Gider</span><strong>'+money(paid-expense)+'</strong></div></div><div class="grid cols"><div class="card"><div class="section-title"><h2>Ödemeler</h2><button class="btn primary" onclick="addPayment()">+ Ödeme Ekle</button></div>'+p.map(x=>'<div class="row"><b>'+money(x.amount)+'</b><span>'+esc(TR[x.status]||x.status)+'</span><span>'+esc(x.due_date||'—')+'</span><button class="btn" '+(x.status==='odendi'?'disabled':'onclick="markPayment(\''+x.id+'\')"')+'>Ödendi</button></div>').join('')+'</div><div class="card"><div class="section-title"><h2>Giderler</h2><button class="btn" onclick="addCost()">+ Gider Ekle</button></div>'+V.data.costEntries.map(x=>'<div class="row"><b>'+esc(x.title)+'</b><span>'+money(x.amount)+'</span><span>'+esc(x.incurred_on)+'</span></div>').join('')+'</div></div>','Finans Merkezi','GİZLİ · SUPER ADMIN')}
function addCost(){modal('Gider Ekle','<div class="form"><label>Gider adı<input id="costTitle"></label><label>Tutar (TL)<input id="costAmount" type="number" min="1"></label><label>Tarih<input id="costDate" type="date" value="'+new Date().toISOString().slice(0,10)+'"></label><label>Not<input id="costNotes"></label></div>','<button class="btn" onclick="closeModal()">Vazgeç</button><button class="btn primary" onclick="saveCost()">Kaydet</button>')}
async function saveCost(){const title=val('costTitle'),amount=Number(val('costAmount'));if(!title||!Number.isFinite(amount)||amount<=0)return alert('Gider adı ve geçerli tutar gerekli.');const {data:{user}}=await CLOUD.auth.getUser();const {error}=await CLOUD.from('cost_entries').insert({title,amount,incurred_on:val('costDate'),notes:val('costNotes'),sector:V.sector,created_by:user.id});if(error)return cloudErr(error);closeModal();await refresh()}

