function presentation(type){sessionStorage.setItem('vertex_presentation',type&&P[type]?type:'home');document.getElementById('presentation')?.remove();document.body.insertAdjacentHTML('beforeend','<div class="presentation presentation-v3" id="presentation"><button class="presentation-exit back-btn" onclick="exitPresentation()" aria-label="Yönetici paneline geri dön"><span>←</span> Yönetici Paneline Dön</button><div id="presentationBody"></div></div>');if(type&&P[type])presentationDeck(type,0);else presentationHome()}
const PRESENTATION_PHOTOS={emlak:{hero:'assets/presentation/emlak-hero.jpg',detail:'assets/presentation/emlak-room.jpg'},kuyum:{hero:'assets/presentation/kuyum-hero.jpg',detail:'assets/presentation/kuyum-detail.jpg'},otel:{hero:'assets/presentation/otel-hero.jpg',detail:'assets/presentation/otel-room.jpg'}};
function presentationHome(){V.presentationState=null;document.getElementById('presentation').classList.add('presentation-at-home');const b=document.getElementById('presentationBody');b.innerHTML='<div class="presentation-home"><button class="presentation-home-back back-btn" onclick="exitPresentation()"><span>←</span> Geri</button><div class="presentation-logo"><img src="'+VERTEX_LOGO+'" alt="VERTEX FLUX"></div><div class="eyebrow">VERTEX DIGITAL EXPERIENCE</div><h1>Müşterinize hangi <span>hikâyeyi anlatacaksınız?</span></h1><p>Sunumu sektör seçerek başlatın. Oklarla sayfa sayfa ilerleyin.</p><div class="presentation-sector-grid">'+[['emlak','EMLAK','Portföyü deneyime dönüştür'],['kuyum','KUYUM','Işıltıyı dijitale taşı'],['otel','OTEL & TURİZM','Misafir gelmeden deneyimi başlat']].map(x=>'<button class="presentation-sector-'+x[0]+'" onclick="presentationDeck(\''+x[0]+'\',0)"><img src="'+PRESENTATION_PHOTOS[x[0]].hero+'" alt="" loading="lazy"><b>'+x[1]+'</b><small>'+x[2]+'</small><span>Sunumu başlat →</span></button>').join('')+'</div><small class="pitch-disclaimer">Görseller temsili stok fotoğraftır; VERTEX müşteri çalışması veya 360 tur kaydı değildir.</small></div>'}
function pitchMobile(type,photo,qr){const content={emlak:{eyebrow:'360° PORTFÖY TURU',title:'Salon · 1 / 6',chips:['Salon','Mutfak','Yatak Odası'],action:'Turu keşfet →',icon:'◎'},kuyum:{eyebrow:'DİJİTAL KOLEKSİYON',title:'Özel seçki',chips:['Yüzük','Kolye','Bileklik'],action:'Ürünleri incele →',icon:'◇'},otel:{eyebrow:'MOBİL TESİS REHBERİ',title:'Oda ve tesis',chips:['Odalar','Havuz','Restoran'],action:'Tesisi keşfet →',icon:'⌂'}}[type];return '<div class="pitch-mobile pitch-mobile-'+type+(qr?' pitch-mobile-qr':'')+'"><div class="pitch-mobile-bar"><span>VERTEX</span><span>•••</span></div><div class="pitch-mobile-photo"><img src="'+photo+'" alt="'+type+' mobil sunumunda temsili içerik" loading="lazy"><span class="pitch-mobile-badge">'+content.icon+' '+content.eyebrow+'</span>'+(type==='emlak'?'<span class="pitch-mobile-hotspot" aria-hidden="true">＋</span>':'')+'</div><div class="pitch-mobile-details"><small>'+(qr?'QR İLE AÇILAN ÖRNEK EKRAN':'ÖRNEK MOBİL SUNUM')+'</small><b>'+content.title+'</b><div class="pitch-mobile-chips">'+content.chips.map(x=>'<span>'+x+'</span>').join('')+'</div><div class="pitch-mobile-action">'+content.action+'</div></div></div>'}
function deckVisual(s,type){if(s.kind==='compare')return '<div class="pitch-table"><div class="pitch-tr pitch-th"><b>Hizmet</b><b>VERTEX teklifi</b><b>Yalnız fotoğraf</b><b>Yalnız video</b></div>'+s.rows.map(r=>'<div class="pitch-tr"><span>'+esc(r[0])+'</span><strong>'+esc(r[1])+'</strong><span>'+esc(r[2])+'</span><span>'+esc(r[3])+'</span></div>').join('')+'</div>';const photos=PRESENTATION_PHOTOS[type],photo=s.kind==='hero'||s.kind==='close'?photos.hero:photos.detail,mobilePhoto=photo===photos.hero?photos.detail:photos.hero;if(s.kind==='qr')return '<div class="qr-scene pitch-photo-scene"><img class="pitch-landscape" src="'+photo+'" alt="'+esc(type)+' için temsili fotoğraf"><div class="qr-phone">'+pitchMobile(type,mobilePhoto,true)+'</div><div class="qr-rings"></div></div>';return '<div class="pitch-photo-scene"><img class="pitch-landscape" src="'+photo+'" alt="'+esc(type)+' için temsili fotoğraf"><div class="pitch-photo-info"><img src="'+VERTEX_LOGO+'" alt=""><span>'+({emlak:'360° · FOTOĞRAF · QR',kuyum:'ÜRÜN · GÖRSEL · KOLEKSİYON',otel:'ODA · TESİS · DENEYİM'})[type]+'</span></div><div class="pitch-screen">'+pitchMobile(type,mobilePhoto,false)+'</div></div>'}
function presentationDeck(type,i){if(!P[type]||!Number.isInteger(i)||i<0||i>=P[type].slides.length)return presentationHome();document.getElementById('presentation').classList.remove('presentation-at-home');V.presentationState={type,index:i};const d=P[type],s=d.slides[i],last=i===d.slides.length-1;document.getElementById('presentationBody').innerHTML='<div class="pitch pitch-'+type+'"><div class="pitch-top"><button class="presentation-back back-btn" onclick="'+(i?'presentationDeck(\''+type+'\','+(i-1)+')':'presentationHome()')+'"><span>←</span> '+(i?'Geri':'Sektörler')+'</button><div class="pitch-count">0'+(i+1)+' / 0'+d.slides.length+'</div></div><div class="pitch-main"><div class="pitch-copy"><div class="eyebrow">'+esc(s.kicker)+'</div><h1>'+esc(s.title)+'</h1><p>'+esc(s.text)+'</p>'+(s.points?'<div class="pitch-points">'+s.points.map(x=>'<div><i>✓</i><span>'+esc(x)+'</span></div>').join('')+'</div>':'')+'</div><div class="pitch-media">'+deckVisual(s,type)+'</div></div><div class="pitch-bottom"><div><b>'+esc(d.title)+'</b><span>'+esc(d.tag)+'</span></div><small class="pitch-disclaimer">Temsili stok fotoğraf · Gerçek müşteri çalışması değildir</small><button class="pitch-next" onclick="'+(last?'presentationHome()':'presentationDeck(\''+type+'\','+(i+1)+')')+'">'+(last?'Sunumları Bitir':'Sonraki Sayfa')+' <span>→</span></button></div></div>'}
document.addEventListener('keydown',e=>{if(!document.getElementById('presentation')||e.altKey||e.ctrlKey||e.metaKey||['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))return;const state=V.presentationState;if(e.key==='ArrowRight'&&state){e.preventDefault();if(state.index<P[state.type].slides.length-1)presentationDeck(state.type,state.index+1);else presentationHome()}if(e.key==='ArrowLeft'&&state){e.preventDefault();if(state.index>0)presentationDeck(state.type,state.index-1);else presentationHome()}});
function presentationOpen(type){presentationDeck(type,0)}
function presentationDetail(type,i){presentationDeck(type,Math.min(i,P[type].slides.length-1))}
async function exitPresentation(){const password=prompt('Yönetici şifrenizi girin');if(password===null)return;try{const {data:{user},error:userError}=await CLOUD.auth.getUser();if(userError||!user?.email)throw Error('Oturum doğrulanamadı');const {error}=await CLOUD.auth.signInWithPassword({email:user.email,password});if(error)throw error;sessionStorage.removeItem('vertex_presentation');document.getElementById('presentation')?.remove()}catch(e){alert('Şifre doğrulanamadı. Sunum açık kalacak.')}}
async function logout(){sessionStorage.removeItem('vertex_presentation');await CLOUD.auth.signOut();login()}
function login(){document.getElementById('app').innerHTML='<div class="login"><div class="loginbox"><div class="login-logo"><img src="'+VERTEX_LOGO+'"></div><div class="eyebrow">VERTEX PRIVATE CONTROL SYSTEM</div><h1>FLUX <span>2.0</span></h1><p class="login-sub">Merkezi yönetim sistemine güvenli giriş</p><label class="pin-label">E-POSTA<input id="email" type="email" placeholder="E-posta adresiniz" autocomplete="username"></label><label class="pin-label">ŞİFRE<input id="password" type="password"></label><button class="btn primary login-button" onclick="auth()">Sisteme Gir →</button><button class="forgot-password" onclick="forgotPassword()">Şifremi Unuttum</button></div></div>'}
async function auth(){const email=val('email'),password=val('password');if(!email||!password)return alert('E-posta ve şifre gerekli.');const {error}=await CLOUD.auth.signInWithPassword({email,password});if(error)return cloudErr(error);await refresh()}
async function forgotPassword(){const email=val('email');if(!email)return alert('Şifre yenileme bağlantısı için e-posta adresinizi girin.');const {error}=await CLOUD.auth.resetPasswordForEmail(email,{redirectTo:location.origin+location.pathname});if(error)return cloudErr(error);alert('Şifre yenileme bağlantısı gönderildi.')}
function recoveryScreen(){document.getElementById('app').innerHTML='<div class="login"><div class="loginbox"><div class="login-logo"><img src="'+VERTEX_LOGO+'"></div><div class="eyebrow">ŞİFRE YENİLEME</div><h1>Yeni şifre</h1><label class="pin-label">YENİ ŞİFRE<input id="newPassword" type="password" minlength="8"></label><button class="btn primary login-button" onclick="setNewPassword()">Şifreyi Güncelle →</button></div></div>'}
async function setNewPassword(){const password=val('newPassword');if(password.length<8)return alert('Şifre en az 8 karakter olmalı.');const {error}=await CLOUD.auth.updateUser({password});if(error)return cloudErr(error);history.replaceState({},'',location.pathname);await refresh()}
async function refresh(){try{await loadCloud();render();const mode=sessionStorage.getItem('vertex_presentation');if(mode&&!document.getElementById('presentation'))presentation(mode==='home'?undefined:mode)}catch(e){cloudErr(e)}}
async function loadGoogleAds(){
  V.googleAds.loading=true;
  try{
    const {data:{session}}=await CLOUD.auth.getSession();
    if(!session?.access_token)throw Error('VERTEX oturumu yok');
    const r=await fetch('/api/google/accounts',{headers:{Authorization:'Bearer '+session.access_token}});
    const d=await r.json();
    V.googleAds={loading:false,ok:!!d.ok,customers:d.customers||[],managerCustomerId:d.managerCustomerId||'1383282213',error:d.ok?null:(d.error||'Google Ads API bağlantısı kurulamadı')};
  }catch(e){V.googleAds={loading:false,ok:false,customers:[],managerCustomerId:'1383282213',error:e.message||String(e)}}
  render();
}
function googleAdsPanel(){
 const g=V.googleAds||{};
 return '<div class="ad-status"><span>GOOGLE ADS BAĞLANTISI</span><b class="'+(g.ok?'ok':'warn')+'">● '+(g.ok?'Canlı API bağlı':g.loading?'Kontrol ediliyor':'Bağlantı kontrolü gerekli')+'</b><small>Manager: '+esc(g.managerCustomerId||'1383282213')+(g.ok?' · Erişilebilir hesap: '+g.customers.length:'')+'</small>'+(g.ok&&g.customers.length?'<div class="google-account-list">'+g.customers.map(x=>'<span class="pill">'+esc(x)+'</span>').join('')+'</div>':'')+(g.error?'<small>'+esc(g.error)+'</small>':'')+'<button class="btn" style="margin-top:10px" onclick="loadGoogleAds()">Google Ads bağlantısını kontrol et →</button></div>';
}
async function googleAdsStatus(){
  try{
    const {data,error}=await CLOUD.rpc('vertex_google_ads_connection_status');
    if(error)throw error;
    return data&&data[0]?data[0]:{connected:false};
  }catch(e){console.error('Google Ads status',e);return {connected:false}}
}
async function finalizeGoogleOAuth(session){
  const q=new URLSearchParams(location.search);
  if(q.get('google')!=='finalize'||!session?.access_token)return;
  try{
    const r=await fetch('/api/google/finalize',{method:'POST',headers:{Authorization:'Bearer '+session.access_token}});
    const data=await r.json().catch(()=>({}));
    history.replaceState({},'',location.pathname+(r.ok?'?google=connected':'?google=error'));
    if(!r.ok)console.error('Google Ads finalize failed',data);
  }catch(e){console.error('Google Ads finalize failed',e);history.replaceState({},'',location.pathname+'?google=error')}
}
async function connectMeta(){location.href='/api/meta/connect'}
async function metaConnectionStatus(){
 try{
  const {data:{session}}=await CLOUD.auth.getSession();
  if(!session?.access_token)return {connected:false};
  const r=await fetch('/api/meta/status',{headers:{Authorization:'Bearer '+session.access_token}});
  return await r.json();
 }catch(e){console.error('Meta status',e);return {connected:false,error:e.message}}
}
async function finalizeMetaOAuth(session){
  const q=new URLSearchParams(location.search);
  if(q.get('meta')!=='finalize'||!session?.access_token)return;
  try{
    const r=await fetch('/api/meta/finalize',{method:'POST',headers:{Authorization:'Bearer '+session.access_token}});
    const data=await r.json().catch(()=>({}));
    history.replaceState({},'',location.pathname+(r.ok?'?meta=connected':'?meta=error'));
    if(!r.ok)console.error('Meta finalize failed',data);
  }catch(e){console.error('Meta finalize failed',e);history.replaceState({},'',location.pathname+'?meta=error')}
}
async function bootstrap(){try{if(!CLOUD)return login();CLOUD.auth.onAuthStateChange((event)=>{if(event==='SIGNED_OUT')login();if(event==='PASSWORD_RECOVERY')setTimeout(recoveryScreen,0)});const {data:{session},error}=await CLOUD.auth.getSession();if(error)throw error;if(location.hash.includes('type=recovery')&&session)return recoveryScreen();if(!session)return login();await finalizeGoogleOAuth(session);await finalizeMetaOAuth(session);await refresh()}catch(e){console.error('VERTEX bootstrap error',e);login()}}
bootstrap();
